// Critters: the whole app as a 1-bit print.
//
// A five-tone ordered dither is the page's constant identity, playing or
// not; the damage moves through it as torn clouds that drift with the
// song, coarsening the print rather than replacing it. Inside a cloud the
// tone count crushes a little, the grid chunks, static fizzes with the
// mix level, and bright pixels grow column-aligned sort tails. At a
// cloud's hottest core the picture is bitten out entirely, through a
// coarse diamond screen, the way the game cuts a chunk from a scene. The
// clouds belong to the music: paused, they all but vanish and the plain
// print is the whole look. Under the cursor the page is simply the page:
// a clear circle, no ink tricks at all.
//
// The swathes slot is a hand-set knob, not a signal: 0.5 is the look as
// designed, 0 turns the clouds off outright, 1 doubles them.
//
// @slot 0: kick
// @slot 1: mix
// @slot 2: drift
// @slot 3: swathes

fn critters_bayer(cell: vec2<f32>) -> f32 {
    let p = vec2<u32>(u32(max(cell.x, 0.0)), u32(max(cell.y, 0.0)));
    let x = (p.x ^ p.y) & 7u;
    let y = p.y & 7u;
    let v = ((x & 1u) * 2u + (y & 1u)) * 16u
        + (((x >> 1u) & 1u) * 2u + ((y >> 1u) & 1u)) * 4u
        + ((x >> 2u) * 2u + (y >> 2u));
    return (f32(v) + 0.5) / 64.0;
}

fn critters_hash(p: vec2<f32>) -> f32 {
    return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453);
}

fn critters_noise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * (3.0 - 2.0 * f);
    let a = critters_hash(i);
    let b = critters_hash(i + vec2<f32>(1.0, 0.0));
    let c = critters_hash(i + vec2<f32>(0.0, 1.0));
    let d = critters_hash(i + vec2<f32>(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn critters_luma(color: vec4<f32>) -> f32 {
    return dot(color.rgb, vec3<f32>(0.2126, 0.7152, 0.0722));
}

fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let kick = clamp(params.signals[0].x, 0.0, 1.0);
    let loudness = clamp(params.signals[0].y, 0.0, 1.0);
    let drift = params.signals[0].z;
    let swathes = clamp(params.signals[0].w, 0.0, 1.0) * 2.0;
    let playing = clamp(params.user_meta[0].z, 0.0, 1.0);

    let res = max(params.resolution, vec2<f32>(1.0));
    let px = uv * res;
    let aspect = vec2<f32>(res.x / res.y, 1.0);

    // The clouds: two octaves of noise on opposing orbits of the drift
    // phase, thresholded high, so the damage reads as torn patches
    // drifting through the print rather than stripes crossing it. The
    // kick barely touches the field; a steady kick holding the mask open
    // is what made the play state a different shader than the idle one.
    // The clouds belong to the music outright: paused, the mask drops to
    // a whisper and the plain print carries the look alone. The hand-set
    // swathes knob scales the whole thing, off at 0, doubled at 1.
    let orbit = vec2<f32>(cos(6.28318530718 * drift), sin(6.28318530718 * drift));
    let n1 = critters_noise(
        uv * aspect * 4.0 + orbit * 1.2 + vec2<f32>(params.time * 0.02, -params.time * 0.015),
    );
    let n2 = critters_noise(
        uv * aspect * 9.0 - orbit * 1.8 + vec2<f32>(-params.time * 0.012, params.time * 0.018),
    );
    let field = n1 * 0.62 + n2 * 0.38 + kick * 0.05;
    let alive = (0.06 + 0.94 * playing) * swathes;
    let m = clamp(smoothstep(0.60, 0.80, field) * alive, 0.0, 1.0);

    // Sampling grid: native on clean paper, chunked inside a swathe, and
    // chunked harder when the kick lands there.
    let chunk = 1.0 + floor(m * (1.0 + kick) + 0.25);
    let cell = floor(px / chunk);
    let src = textureSampleLevel(screen, samp, (cell + 0.5) * chunk / res, 0.0);
    var luma = critters_luma(src);

    // The sort tails: a fragment pass can't truly sort a column, so inside
    // a swathe every bright pixel grows a downward comet tail instead,
    // column-aligned, its length rolled per column so a run of streaks
    // comes out ragged the way a real sort does. Eight taps, always taken,
    // gated by the mask at the end.
    let colw = max(chunk, 3.0);
    let col = floor(px.x / colw);
    let ragged = 0.35 + 0.65 * critters_hash(vec2<f32>(col, floor(drift * 48.0)));
    let tail = (6.0 + 22.0 * kick) * ragged / res.y;
    let colx = (col + 0.5) * colw / res.x;
    var streak = 0.0;
    for (var j = 1; j < 9; j = j + 1) {
        let back = f32(j) / 8.0;
        let above = vec2<f32>(colx, clamp(uv.y - back * tail, 0.0, 1.0));
        let l = critters_luma(textureSampleLevel(screen, samp, above, 0.0));
        // Only genuinely bright sources spawn a tail; dim rows dripping
        // was what whited out whole panels.
        streak = max(streak, smoothstep(0.4, 0.8, l) * l * (1.0 - back * back));
    }
    luma = max(luma, streak * m * 0.7);

    // Static rides the swathes when the mix runs loud, faintly.
    luma += (critters_hash(cell + floor(drift * 883.0)) - 0.5) * 0.06 * loudness * m;

    // Tone count: a five-tone print on clean paper, unmissable on a dark
    // palette, so the dither is the page's constant identity and a swathe
    // only coarsens it. Light themes get a little more headroom, since
    // paper shows every tone the way black swallows them. The matrix
    // crawls a cell at a time with the drift phase, never smoothly, so
    // text stays print-stable.
    let paper = mix(5.0, 7.0, clamp(params.user_meta[1].x, 0.0, 1.0));
    let tones = mix(paper, mix(4.0, 3.0, kick), m);
    let crawl = floor(vec2<f32>(drift, drift * 0.5) * 8.0);
    let threshold = critters_bayer(cell + crawl);
    let steps = max(tones - 1.0, 1.0);
    let q = clamp(floor(luma * steps + threshold) / steps, 0.0, 1.0);

    // The bite: at a cloud's hottest core the picture is cut out
    // entirely, through a coarse diamond screen so the hole's edge is the
    // game's chunky pattern rather than a soft fade.
    let coarse = critters_bayer(floor(px / 10.0));
    let bite = smoothstep(0.84, 0.96, field) * alive;
    let inked = q * (1.0 - step(coarse, bite));

    // The lamp: the composed frame untouched inside the circle, easing
    // back into the print at the rim.
    let raw = textureSampleLevel(screen, samp, uv, 0.0);
    let lamp = 1.0 - smoothstep(0.09, 0.18, length((uv - params.mouse.xy / res) * aspect));
    return vec4<f32>(mix(vec3<f32>(inked), raw.rgb, lamp), 1.0);
}

// Serpent: the back wall of the Snake chapter.
//
// Two fields of folded value noise, printed straight to three tones with
// its own Bayer pass, so the panel is full print whatever the screen
// shader is doing. Every bit of motion hangs off the drift phase, which
// is music-driven time: paused, the coil holds perfectly still no matter
// how often the window repaints. The kick moves nothing. It lifts the
// second field through the first instead, so a hit reads as something
// surfacing rather than the whole wall flinching.
//
// @slot 0: kick
// @slot 1: mix
// @slot 2: drift

fn serpent_hash(p: vec2<f32>) -> f32 {
    return fract(sin(dot(p, vec2<f32>(127.1, 311.7))) * 43758.5453);
}

fn serpent_noise(p: vec2<f32>) -> f32 {
    let i = floor(p);
    let f = fract(p);
    let u = f * f * (3.0 - 2.0 * f);
    let a = serpent_hash(i);
    let b = serpent_hash(i + vec2<f32>(1.0, 0.0));
    let c = serpent_hash(i + vec2<f32>(0.0, 1.0));
    let d = serpent_hash(i + vec2<f32>(1.0, 1.0));
    return mix(mix(a, b, u.x), mix(c, d, u.x), u.y);
}

fn serpent_fbm(p: vec2<f32>) -> f32 {
    var value = 0.0;
    var amp = 0.5;
    var q = p;
    for (var i = 0; i < 4; i = i + 1) {
        value += amp * serpent_noise(q);
        q = q * 2.03 + vec2<f32>(17.0, 9.2);
        amp *= 0.5;
    }
    return value;
}

fn serpent_bayer(cell: vec2<f32>) -> f32 {
    let p = vec2<u32>(u32(max(cell.x, 0.0)), u32(max(cell.y, 0.0)));
    let x = (p.x ^ p.y) & 7u;
    let y = p.y & 7u;
    let v = ((x & 1u) * 2u + (y & 1u)) * 16u
        + (((x >> 1u) & 1u) * 2u + ((y >> 1u) & 1u)) * 4u
        + ((x >> 2u) * 2u + (y >> 2u));
    return (f32(v) + 0.5) / 64.0;
}

fn fs_user(uv: vec2<f32>) -> vec4<f32> {
    let kick = clamp(params.signals[0].x, 0.0, 1.0);
    let loudness = clamp(params.signals[0].y, 0.0, 1.0);
    let drift = params.signals[0].z;

    let res = max(params.resolution, vec2<f32>(1.0));
    let p = (uv - 0.5) * vec2<f32>(res.x / res.y, 1.0);

    // Music time as a point on a circle: continuous through the phase
    // wrap, and frozen the moment the music is. The two fields orbit in
    // opposite directions so they never read as one sliding image.
    let phase = 6.28318530718 * drift;
    let orbit = vec2<f32>(cos(phase), sin(phase));

    // The wall: noise moved by noise, drifting on the orbit. The warp
    // strength is fixed; nothing here jitters with the music.
    let warp_a = vec2<f32>(
        serpent_fbm(p * 1.7 + orbit * 0.6),
        serpent_fbm(p * 1.7 - orbit * 0.4 + vec2<f32>(4.7, 1.3)),
    );
    let body_a = serpent_fbm(p * 2.6 + (warp_a - 0.5) * 1.8 + orbit * 0.3);
    let ridge_a = abs(sin((body_a * 6.0 + phase * 0.5) * 3.14159));
    let ink_a = pow(ridge_a, 2.6) * (0.35 + 0.65 * body_a) * (0.5 + 0.5 * loudness);

    // The thing beneath it: finer scales, turned against the wall's grain,
    // riding the orbit backwards. It's always there, and the kick is only
    // a lamp on it.
    let q = vec2<f32>(p.x * 0.36 - p.y * 0.93, p.x * 0.93 + p.y * 0.36);
    let warp_b = vec2<f32>(
        serpent_fbm(q * 3.1 - orbit * 0.5),
        serpent_fbm(q * 3.1 + orbit * 0.7 + vec2<f32>(8.1, 3.9)),
    );
    let body_b = serpent_fbm(q * 4.2 + (warp_b - 0.5) * 1.4 - orbit * 0.4);
    let ridge_b = abs(sin((body_b * 8.0 - phase * 0.5) * 3.14159));
    let reveal = smoothstep(0.15, 0.85, kick);
    let ink_b = pow(ridge_b, 2.0) * (0.4 + 0.6 * body_b) * reveal;

    let ink = clamp(max(ink_a, ink_b), 0.0, 1.0);

    // Printed on the way out: three tones through the same matrix the
    // screen pass uses, so the panel is dithered even where the swathes
    // aren't. The screen pass quantizing this again is harmless, since a
    // three-tone image re-reads as itself.
    let threshold = serpent_bayer(floor(uv * res));
    let printed = clamp(floor(ink * 2.0 + threshold) / 2.0, 0.0, 1.0);
    return vec4<f32>(vec3<f32>(printed), 1.0);
}
